{"implementation":"def solve(case):
    nodes = case.get("nodes", [])
    required = set(case.get("required_symbols", []))
    by_id = {node["id"]: node for node in nodes}
    retained = set()

    for node in nodes:
        if not node.get("removable", False) or node.get("symbol") in required:
            current = node
            seen = set()
            while current is not None and current["id"] not in seen:
                seen.add(current["id"])
                retained.add(current["id"])
                parent_id = current.get("parent")
                current = by_id.get(parent_id) if parent_id is not None else None

    removed_node_ids = [node["id"] for node in nodes if node["id"] not in retained]
    retained_node_ids = [node["id"] for node in nodes if node["id"] in retained]
    return {
        "removed_node_ids": removed_node_ids,
        "retained_node_ids": retained_node_ids,
    }"}
